    R"SQL(SELECT g, toString(b) AS bt, bstr, arrayStringConcat(arrayMap(x -> toString(x), sumForEach(dc)), ','), toString(sum(dcount)) AS c1, toString(sum(dsum)) AS c2 FROM (SELECT if(arrayStringConcat([Attributes['span.name']], char(31)) IN ('request.validate'), arrayStringConcat([Attributes['span.name']], char(31)), '__other__') AS g, 0 + intDiv(toUnixTimestamp64Milli(TimeUnix) - 0, 60000) * 60000 AS b, arrayStringConcat(arrayMap(x -> toString(x), ExplicitBounds), ',') AS bstr, BucketCounts AS dc, toFloat64(Count) AS dcount, Sum AS dsum FROM `otel`.`otel_metrics_histogram` PREWHERE ServiceName = 'api_service' AND MetricName = 'http.server.request.duration' AND TimeUnix >= fromUnixTimestamp64Milli(1789860160999) AND TimeUnix <= fromUnixTimestamp64Milli(1789867360999) WHERE 1) GROUP BY g, b, bstr ORDER BY g, b, bstr LIMIT 300001 SETTINGS max_execution_time = 30, max_memory_usage = 2000000000, max_bytes_before_external_group_by = 1000000000, max_bytes_before_external_sort = 1000000000)SQL";

// rank-summary-p50-2 [2]
inline constexpr const char* kSeriesKeepSummary =
    R"SQL(SELECT toString(sid) AS g, any(attrs), toString(b), toString(argMax(qv, TimeUnix)) AS c1 FROM (SELECT cityHash64(Attributes, ResourceAttributes, ScopeName, ScopeVersion) AS sid, toJSONString(Attributes) AS attrs, 0 + intDiv(toUnixTimestamp64Milli(TimeUnix) - 0, 60000) * 60000 AS b, TimeUnix, indexOf(`ValueAtQuantiles.Quantile`, 0.5) AS qi, `ValueAtQuantiles.Value`[qi] AS qv FROM `otel`.`otel_metrics_summary` PREWHERE ServiceName = 'api_service' AND MetricName = 'span.duration.summary' AND TimeUnix >= fromUnixTimestamp64Milli(1789860160999) AND TimeUnix <= fromUnixTimestamp64Milli(1789867360999) WHERE 1) WHERE qi > 0 AND toString(sid) IN ('4574312782914746434') GROUP BY sid, b ORDER BY sid, b LIMIT 300001 SETTINGS max_execution_time = 30, max_memory_usage = 2000000000, max_bytes_before_external_group_by = 1000000000, max_bytes_before_external_sort = 1000000000)SQL";

